using System.Data;
namespace StokTakipUygulamasi;
internal sealed class frmAnaSayfa:Form
{
    readonly Session user;readonly DataGridView products,cart;readonly MaskedTextBox phone;readonly TextBox customer,note,total,search;long customerId;
    public frmAnaSayfa(Session user){this.user=user;Ui.Setup(this,"Stok Takip • Satış İşlemi",1280,780);MinimumSize=new Size(1060,760);KeyPreview=true;
        var root=UiLayout.Root(this,3);UiLayout.Row(root,0,54);UiLayout.Row(root,1,58);UiLayout.Row(root,2,100,false);
        var header=UiLayout.Table(2,1);UiLayout.Col(header,0,65,false);UiLayout.Col(header,1,35,false);UiLayout.Add(header,UiLayout.Heading("Stok Takip" ,22),0,0);var identity=UiLayout.Caption(user.Name+"  /  "+(user.Role==1?"Yönetici":"Personel"));identity.TextAlign=ContentAlignment.MiddleRight;UiLayout.Add(header,identity,1,0);UiLayout.Add(root,header,0,0);
        var nav=UiLayout.Table(user.Role==1?6:5,1);UiLayout.Add(root,nav,0,1,margin:new Padding(0,0,0,12));int navIndex=0;
        void Menu(string label,Func<Form> make){int i=navIndex++;UiLayout.Add(nav,UiLayout.Button(label,()=>{if(HasDraft()&&!Ui.Confirm("Mevcut satış taslağı silinecek. Devam edilsin mi?"))return;using var f=make();f.ShowDialog(this);Reload();ClearCart();}),i,0,margin:new Padding(i==0?0:5,0,i==nav.ColumnCount-1?0:5,0));}
        Menu("Tedarikçiler",()=>new frmTedarikciIslemleri());Menu("Ürünler",()=>new frmUrunIslemleri());Menu("Satış detayları",()=>new frmSatisDetaylari());Menu("Müşteriler",()=>new frmMusteriIslemleri());if(user.Role==1)Menu("Personeller",()=>new frmPersonelIslemleri(user));Menu("Azalan stok",()=>new frmStokuAzalanUrunler());
        var body=UiLayout.Table(2,1);UiLayout.Col(body,0,55,false);UiLayout.Col(body,1,45,false);UiLayout.Add(root,body,0,2);
        var left=UiLayout.Card(1,3);UiLayout.Row(left,0,38);UiLayout.Row(left,1,58);UiLayout.Row(left,2,100,false);UiLayout.Add(body,left,0,0,margin:new Padding(0,0,6,0));UiLayout.Add(left,UiLayout.Heading("Ürün listesi"),0,0);search=UiLayout.Text();search.PlaceholderText="Ürün adı, kodu veya kategori…";UiLayout.Add(left,UiLayout.Field("Ürün ara  •  Ctrl+F",search),0,1,margin:new Padding(0,0,0,8));products=UiLayout.Grid();UiLayout.Add(left,products,0,2);search.TextChanged+=(_,_)=>Ui.Safe(Reload);products.CellDoubleClick+=(_,e)=>{if(e.RowIndex>=0)Ui.Safe(AddItem);};
        var sale=UiLayout.Card(1,7);UiLayout.Add(body,sale,1,0,margin:new Padding(6,0,0,0));UiLayout.Row(sale,0,38);UiLayout.Row(sale,1,68);UiLayout.Row(sale,2,64);UiLayout.Row(sale,3,40);UiLayout.Row(sale,4,100,false);UiLayout.Row(sale,5,76);UiLayout.Row(sale,6,70);UiLayout.Add(sale,UiLayout.Heading("Satış işlemi"),0,0);
        var customerLookup=UiLayout.Table(3,1,Theme.Surface);UiLayout.Col(customerLookup,0,100,false);UiLayout.Col(customerLookup,1,70);UiLayout.Col(customerLookup,2,85);phone=UiLayout.Phone();UiLayout.Add(customerLookup,UiLayout.Field("Müşteri telefonu",phone),0,0,margin:new Padding(0,0,8,8));UiLayout.Add(customerLookup,UiLayout.Button("Seç",FindCustomer),1,0,margin:new Padding(0,24,0,8));UiLayout.Add(customerLookup,UiLayout.Button("Liste",PickCustomer),2,0,margin:new Padding(6,24,0,8));UiLayout.Add(sale,customerLookup,0,1);
        customer=UiLayout.Text(readOnly:true);UiLayout.Add(sale,UiLayout.Field("Müşteri",customer),0,2,margin:new Padding(0,0,0,8));phone.TextChanged+=(_,_)=>{customerId=0;customer.Clear();};
        var actions=UiLayout.Table(2,1,Theme.Surface);UiLayout.Add(actions,UiLayout.Button("+ Ürün ekle",AddItem,true),0,0,margin:new Padding(0,0,4,8));UiLayout.Add(actions,UiLayout.Button("− Ürün çıkar",()=>{if(cart.SelectedRows.Count==0)throw new InvalidOperationException("Satış listesinden ürün seçiniz.");cart.Rows.Remove(cart.SelectedRows[0]);Calculate();}),1,0,margin:new Padding(4,0,0,8));UiLayout.Add(sale,actions,0,3);
        cart=UiLayout.Grid(true);UiLayout.Add(sale,cart,0,4);foreach(var (n,h) in new[]{("Code","Kod"),("Name","Ürün Adı"),("Qty","Miktar"),("Price","Birim Fiyat"),("Sum","Toplam")})cart.Columns.Add(new DataGridViewTextBoxColumn{Name=n,HeaderText=h,ReadOnly=n!="Qty",SortMode=DataGridViewColumnSortMode.NotSortable});cart.Columns["Name"].FillWeight=180;cart.Columns["Code"].FillWeight=45;cart.Columns["Qty"].FillWeight=65;
        note=UiLayout.Text(true);UiLayout.Add(sale,UiLayout.Field("Satış notu",note),0,5,margin:new Padding(0,8,0,0));var footer=UiLayout.Table(2,1,Theme.Surface);total=UiLayout.Text(readOnly:true);UiLayout.Add(footer,UiLayout.Field("Genel toplam",total),0,0,margin:new Padding(0,8,6,0));UiLayout.Add(footer,UiLayout.Button("Satış yap",Sell,true),1,0,margin:new Padding(6,32,0,0));UiLayout.Add(sale,footer,0,6);
        cart.CellValidating+=(_,e)=>{if(e.RowIndex<0||cart.Columns[e.ColumnIndex].Name!="Qty")return;if(!int.TryParse(Db.Str(e.FormattedValue),out int q)||q<=0||q>AvailableStock(Db.Number(cart.Rows[e.RowIndex].Cells["Code"].Value))){e.Cancel=true;Ui.Info("Miktar pozitif ve mevcut stoktan fazla olmamalıdır.");}};cart.CellEndEdit+=(_,_)=>Calculate();cart.DataError+=(_,e)=>{e.ThrowException=false;Ui.Info("Geçersiz miktar.");};Reload();Calculate();
        phone.KeyDown+=(_,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;Ui.Safe(FindCustomer);}};
        KeyDown+=(_,e)=>{if(e.Control&&e.KeyCode==Keys.F){e.SuppressKeyPress=true;search.Focus();search.SelectAll();}else if(e.KeyCode==Keys.F5){e.SuppressKeyPress=true;Ui.Safe(Reload);}};
        FormClosing+=(_,e)=>{if(HasDraft()&&!Ui.Confirm("Tamamlanmamış satış taslağı silinsin mi?"))e.Cancel=true;};
    }
    void Reload()=>Ui.Bind(products,Db.Query(Db.Products+" WHERE @p0='' OR tr_contains(u.urun_adi,@p0) OR tr_contains(CAST(u.urun_kodu AS TEXT),@p0) OR tr_contains(k.kategori_adi,@p0) ORDER BY u.urun_adi",search.Text.Trim()));
    bool HasDraft()=>cart.Rows.Count>0 || customerId!=0 || note.TextLength>0;
    void PickCustomer(){using var picker=new CustomerPicker();if(picker.ShowDialog(this)==DialogResult.OK){phone.Text=picker.PhoneNumber;FindCustomer();}}
    long AvailableStock(long code){try{return Stock(code);}catch{return 0;}}
    long Stock(long code){var d=Db.Query("SELECT stok_adedi FROM urunler WHERE urun_kodu=@p0",code);return d.Rows.Count==0?0:Db.Number(d.Rows[0][0]);}
    void FindCustomer(){var d=Db.Query("SELECT id,ad_soyad FROM musteriler WHERE telefon=@p0",Ui.Phone(phone.Text));customerId=0;customer.Clear();if(d.Rows.Count==0){Ui.Info("Müşteri bulunamadı.");return;}customerId=Db.Number(d.Rows[0][0]);customer.Text=Db.Str(d.Rows[0][1]);}
    void AddItem(){long code=Ui.Selected(products);if(!cart.EndEdit())return;var existing=cart.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>Db.Number(r.Cells["Code"].Value)==code);if(existing!=null){int q=int.Parse(Db.Str(existing.Cells["Qty"].Value));if(q>=AvailableStock(code))throw new InvalidOperationException("Mevcut stok sınırına ulaşıldı.");existing.Cells["Qty"].Value=q+1;Calculate();return;}var r=Db.Query("SELECT urun_adi,stok_adedi,fiyat FROM urunler WHERE urun_kodu=@p0",code).Rows[0];if(Db.Number(r[1])<=0)throw new InvalidOperationException("Bu ürünün stoku yok.");int i=cart.Rows.Add(code,Db.Str(r[0]),1,Db.Number(r[2])/100m,Db.Number(r[2])/100m);cart.Rows[i].Tag=Db.Number(r[2]);Calculate();}
    void Calculate(){decimal sum=0;foreach(DataGridViewRow r in cart.Rows){if(!int.TryParse(Db.Str(r.Cells["Qty"].Value),out int q))continue;decimal subtotal=q*(Db.Number(r.Tag)/100m);r.Cells["Sum"].Value=subtotal.ToString("N2");r.Cells["Price"].Value=(Db.Number(r.Tag)/100m).ToString("N2");sum+=subtotal;}total.Text=sum.ToString("N2")+" ₺";}
    void ClearCart(){cart.CancelEdit();cart.Rows.Clear();customerId=0;phone.Clear();customer.Clear();note.Clear();Calculate();}
    void Sell(){if(!cart.EndEdit())return;var items=cart.Rows.Cast<DataGridViewRow>().Select(r=>(Db.Number(r.Cells["Code"].Value),int.Parse(Db.Str(r.Cells["Qty"].Value)),Db.Number(r.Tag))).ToList();if(!Ui.Confirm("Satışı tamamlamak istiyor musunuz?\nGenel toplam: "+total.Text))return;Db.Sale(customerId,user.Id,note.Text.Trim(),items);ClearCart();Reload();Ui.Info("Satış işlemi başarılı.");}
}
